    }

    .icon-btn {
      width: 2.8rem;
      height: 2.8rem;
      display: inline-grid;
      place-items: center;
      background: rgba(255, 255, 255, 0.04);
      border-color: var(--border);
      color: var(--text);
      cursor: pointer;
