      justify-content: center;
      gap: 0.5rem;
      padding: 0.9rem 1.2rem;
      cursor: pointer;
      text-decoration: none;
    }

    .ghost-btn {
      background: rgba(255, 255, 255, 0.04);
      border-color: var(--border);
      color: var(--text);
    }

    .cta-btn {
      background: linear-gradient(135deg, #8b5cf6, #6d28d9);
      color: white;
      box-shadow: 0 16px 30px rgba(109, 40, 217, 0.28);
    }

    .icon-btn:hover,
    .ghost-btn:hover,
    .cta-btn:hover,
    .chip:hover,
    .icon-btn:focus-visible,
    .ghost-btn:focus-visible,
    .cta-btn:focus-visible,
    .chip:focus-visible {
      transform: translateY(-1px);
      border-color: rgba(255, 255, 255, 0.16);
      outline: none;
    }

    main {
      padding: 1.25rem 0 4rem;
    }

    .hero {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap: 1.5rem;
      padding: 1.25rem 0 3rem;
      align-items: stretch;
    }

    .hero-copy,
    .hero-spotlight,
    .section-card,
    .feature-card,
    .deal-card,
    .editorial-card {
      background: linear-gradient(180deg, rgba(19, 26, 40, 0.96), rgba(12, 16, 25, 0.96));
      border: 1px solid var(--border);
      box-shadow: var(--shadow);
      border-radius: var(--radius-xl);
    }

    .hero-copy {
      padding: clamp(1.5rem, 4vw, 3rem);
      position: relative;
      overflow: hidden;
    }

    .hero-copy::after {
      content: "";
      position: absolute;
      inset: auto -4rem -5rem auto;
      width: 16rem;
      height: 16rem;
      background: radial-gradient(circle, rgba(139, 92, 246, 0.26), transparent 70%);
      pointer-events: none;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      color: #c9d4e8;
      font-size: 0.85rem;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    .eyebrow::before {
      content: "";
      width: 0.7rem;
      height: 0.7rem;
      border-radius: 999px;
      background: linear-gradient(135deg, var(--accent), var(--accent-2));
      box-shadow: 0 0 0 0.3rem rgba(139, 92, 246, 0.14);
    }

    h1, h2, h3, p {
      margin: 0;
    }

    h1 {
      margin-top: 1rem;
      font-size: clamp(2.7rem, 5vw, 4.8rem);
      line-height: 0.94;
      letter-spacing: -0.05em;
      max-width: 11ch;
    }

    .hero-copy p {
      max-width: 58ch;
      margin-top: 1rem;
      color: var(--muted);
      font-size: 1.05rem;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.9rem;
      margin-top: 1.6rem;
    }

    .hero-metrics {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 0.85rem;
      margin-top: 2rem;
    }

    .metric {
      padding: 1rem;
      border-radius: var(--radius-md);
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid rgba(255, 255, 255, 0.06);
    }

    .metric strong {
      display: block;
      font-size: 1.15rem;
    }

    .metric span {
      color: var(--soft);
      font-size: 0.9rem;
    }

    .hero-spotlight {
      padding: 1.2rem;
      display: grid;
      gap: 1rem;
      align-content: stretch;
      overflow: hidden;
    }

    .spotlight-panel {
      border-radius: var(--radius-lg);
      background:
        linear-gradient(135deg, rgba(139, 92, 246, 0.24), rgba(34, 197, 94, 0.12)),
        linear-gradient(180deg, rgba(18, 24, 37, 0.9), rgba(12, 16, 25, 0.98));
      border: 1px solid rgba(255, 255, 255, 0.08);
      padding: 1.2rem;
      min-height: 18rem;
      display: grid;
      gap: 1rem;
      align-content: space-between;
    }

    .spotlight-tag {
      display: inline-flex;
      align-items: center;
      width: fit-content;
      padding: 0.4rem 0.75rem;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.08);
      color: #d7def0;
      font-size: 0.82rem;
    }

    .product-art {
      display: grid;
      place-items: center;
      min-height: 11.5rem;
      border-radius: 22px;
      background:
        radial-gradient(circle at 30% 30%, rgba(255, 255, 255, 0.2), transparent 20%),
        linear-gradient(135deg, rgba(139, 92, 246, 0.95), rgba(15, 23, 42, 0.22)),
        linear-gradient(180deg, #111827, #0a0d13);
      border: 1px solid rgba(255, 255, 255, 0.1);
    }

    .product-art span {
      width: 7rem;
      height: 7rem;
      border-radius: 24px;
      background: rgba(255, 255, 255, 0.12);
      display: grid;
      place-items: center;
      font-size: 2rem;
      font-weight: 700;
      letter-spacing: -0.05em;
    }

    .spotlight-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .section {
      margin-top: 1.5rem;
    }

    .section-head {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1rem;
    }

    .section-head p {
      color: var(--muted);
      max-width: 62ch;
      margin-top: 0.25rem;
    }

    .chips {
      display: flex;
      flex-wrap: wrap;
      gap: 0.6rem;
    }

    .chip {
      padding: 0.65rem 0.95rem;
      background: rgba(255, 255, 255, 0.04);
      border-color: rgba(255, 255, 255, 0.08);
      color: var(--muted);
      cursor: pointer;
    }

    .chip[aria-pressed="true"] {
      background: rgba(139, 92, 246, 0.16);
      color: var(--text);
      border-color: rgba(139, 92, 246, 0.35);
    }

    .grid {
      display: grid;
      gap: 1rem;
    }

    .products {
      grid-template-columns: repeat(4, minmax(0, 1fr));
    }

    .product-card {
      padding: 1rem;
