      background: var(--panel);
      border: 1px solid var(--border);
      overflow: hidden;
    }

    .thumb {
      aspect-ratio: 1 / 1;
      border-radius: 20px;
      display: grid;
      place-items: center;
      margin-bottom: 1rem;
      background:
        linear-gradient(160deg, rgba(139, 92, 246, 0.28), rgba(34, 197, 94, 0.08)),
