    .thumb span {
      font-weight: 700;
      font-size: 1.6rem;
      letter-spacing: -0.04em;
      color: #f3f7ff;
    }

    .product-meta,
    .feature-meta,
    .deal-meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 0.75rem;
    }

    .kicker {
      color: #c3cee2;
      font-size: 0.85rem;
    }

    .price {
      font-weight: 700;
      color: #f8fbff;
    }

    .product-card h3,
    .feature-card h3,
    .deal-card h3,
    .editorial-card h3 {
      font-size: 1.05rem;
      margin-bottom: 0.4rem;
    }

    .product-card p,
    .feature-card p,
    .deal-card p,
    .editorial-card p {
      color: var(--muted);
      font-size: 0.95rem;
    }

    .rating {
      color: #facc15;
      letter-spacing: 0.12em;
      font-size: 0.9rem;
    }

    .feature-grid {
      grid-template-columns: 1.1fr 0.9fr;
    }

    .feature-card {
      padding: 1.3rem;
      display: grid;
      gap: 1rem;
    }

    .feature-card.large {
      padding: 1.4rem;
      min-height: 100%;
    }

    .feature-card .story {
      display: grid;
      gap: 0.85rem;
      align-content: start;
    }

    .feature-visual {
      min-height: 18rem;
      border-radius: 24px;
      background:
        radial-gradient(circle at 30% 25%, rgba(255, 255, 255, 0.16), transparent 18%),
        linear-gradient(140deg, rgba(249, 115, 22, 0.18), rgba(139, 92, 246, 0.24)),
        linear-gradient(180deg, #121a2a, #0d1118);
      border: 1px solid rgba(255, 255, 255, 0.08);
      position: relative;
      overflow: hidden;
    }

    .feature-visual::before,
    .feature-visual::after {
      content: "";
      position: absolute;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.1);
      filter: blur(1px);
    }

    .feature-visual::before {
      width: 11rem;
      height: 11rem;
      right: -1rem;
      top: -1rem;
    }

    .feature-visual::after {
      width: 16rem;
      height: 16rem;
      left: -3rem;
      bottom: -6rem;
    }

    .feature-stack {
      display: grid;
      gap: 1rem;
    }

    .deal-card {
      padding: 1.2rem;
      display: grid;
      gap: 0.9rem;
    }

    .deal-banner {
      display: grid;
      grid-template-columns: auto 1fr;
      gap: 1rem;
      align-items: center;
      padding: 1rem;
      border-radius: 22px;
      background: linear-gradient(135deg, rgba(245, 158, 11, 0.17), rgba(139, 92, 246, 0.12));
      border: 1px solid rgba(255, 255, 255, 0.08);
    }

    .deal-time {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 0.65rem;
    }

    .time-box {
      padding: 0.8rem 0.7rem;
      border-radius: 18px;
      background: rgba(255, 255, 255, 0.04);
      text-align: center;
    }

    .time-box strong {
      display: block;
      font-size: 1.25rem;
    }

    .time-box span {
      color: var(--muted);
      font-size: 0.8rem;
    }

    .deal-list {
      display: grid;
      gap: 0.85rem;
    }

    .deal-item {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 0.95rem 1rem;
      border-radius: 18px;
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid rgba(255, 255, 255, 0.06);
    }

    .deal-item small {
      color: var(--soft);
      display: block;
    }

    .editorial-grid {
      grid-template-columns: 1.1fr 0.9fr 0.9fr;
    }

    .editorial-card {
      padding: 1rem;
      display: grid;
      gap: 0.9rem;
    }

    .editorial-card .visual {
      min-height: 11rem;
      border-radius: 20px;
      border: 1px solid rgba(255, 255, 255, 0.08);
      background: linear-gradient(135deg, rgba(34, 197, 94, 0.2), rgba(139, 92, 246, 0.25));
    }

    .editorial-card:nth-child(2) .visual {
      background: linear-gradient(135deg, rgba(245, 158, 11, 0.18), rgba(255, 255, 255, 0.06));
    }

    .editorial-card:nth-child(3) .visual {
      background: linear-gradient(135deg, rgba(59, 130, 246, 0.16), rgba(139, 92, 246, 0.22));
    }

    footer {
      padding: 2rem 0 3rem;
      color: var(--soft);
    }

    .footer-card {
      margin-top: 1.5rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1rem 1.2rem;
      border-radius: var(--radius-lg);
      border: 1px solid var(--border);
      background: rgba(255, 255, 255, 0.03);
    }

    @media (max-width: 1024px) {
      .hero,
      .feature-grid,
      .editorial-grid {
        grid-template-columns: 1fr;
      }

      .products {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .section-head {
        align-items: start;
        flex-direction: column;
      }
    }

    @media (max-width: 720px) {
      .topbar {
        flex-direction: column;
        align-items: stretch;
      }

      nav,
      .utility,
      .footer-card {
        flex-direction: column;
        align-items: stretch;
      }

      .search {
        width: 100%;
      }

      .hero-metrics,
      .deal-time,
      .products {
        grid-template-columns: 1fr;
      }

      .hero-actions {
        flex-direction: column;
      }

      .deal-banner,
      .spotlight-row {
        grid-template-columns: 1fr;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to content</a>

  <header>
    <div class="shell topbar">
      <a class="brand" href="#" aria-label="Northstar Supply home">
        <span class="brand-mark" aria-hidden="true"></span>
        <span>
          Northstar Supply
          <small>Modern retail essentials</small>
        </span>
      </a>

      <nav aria-label="Primary">
        <a href="#featured">Featured</a>
        <a href="#deals">Deals</a>
        <a href="#stories">Editorial</a>
      </nav>

      <div class="utility">
        <label class="sr-only" for="search">Search products</label>
        <input id="search" class="search" type="search" placeholder="Search jackets, sneakers, home..." />
        <button class="icon-btn" type="button" aria-label="Open cart">🛒</button>
      </div>
    </div>
  </header>

  <main id="main" class="shell">
    <section class="hero" aria-label="Brand highlights">
      <div class="hero-copy">
        <span class="eyebrow">New season collection</span>
        <h1>Premium retail, tuned for everyday living.</h1>
        <p>
          Discover refined essentials, limited-time offers, and editorial picks curated for a clean,
          modern wardrobe and home.
        </p>
        <div class="hero-actions">
          <a class="cta-btn" href="#featured">Shop featured</a>
          <a class="ghost-btn" href="#stories">Read the journal</a>
        </div>
        <div class="hero-metrics" aria-label="Store highlights">
          <div class="metric">
            <strong>120+ items</strong>
            <span>Curated weekly</span>
          </div>
          <div class="metric">
            <strong>2-day ship</strong>
            <span>On core regions</span>
          </div>
          <div class="metric">
            <strong>4.9/5</strong>
            <span>Customer rating</span>
          </div>
        </div>
      </div>

      <aside class="hero-spotlight" aria-label="Spotlight product">
        <div class="spotlight-panel">
          <div class="spotlight-row">
            <span class="spotlight-tag">Spotlight: Trail Runner Pro</span>
            <span>Limited release</span>
          </div>
          <div class="product-art" aria-hidden="true">
            <span>TR</span>
          </div>
          <div class="spotlight-row">
            <div>
              <strong>Trail Runner Pro</strong>
              <div class="kicker">Cushioned mesh / midnight graphite</div>
            </div>
            <div class="price">$148</div>
          </div>
        </div>
      </aside>
    </section>

    <section id="featured" class="section" aria-labelledby="featured-title">
      <div class="section-head">
        <div>
          <h2 id="featured-title">Featured products</h2>
          <p>Best-selling pieces selected for texture, versatility, and elevated everyday wear.</p>
        </div>
        <div class="chips" role="toolbar" aria-label="Filter featured products">
          <button class="chip" type="button" aria-pressed="true" data-filter="all">All</button>
          <button class="chip" type="button" aria-pressed="false" data-filter="apparel">Apparel</button>
          <button class="chip" type="button" aria-pressed="false" data-filter="footwear">Footwear</button>
          <button class="chip" type="button" aria-pressed="false" data-filter="home">Home</button>
        </div>
      </div>
      <div class="grid products" id="productGrid"></div>
    </section>

    <section id="deals" class="section" aria-labelledby="deals-title">
      <div class="section-head">
        <div>
          <h2 id="deals-title">Deals & offers</h2>
          <p>Timed promos, stackable savings, and bundle incentives across top categories.</p>
        </div>
      </div>
      <div class="grid feature-grid">
        <article class="deal-card">
          <div class="deal-banner">
            <span class="spotlight-tag">48-hour event</span>
